/* @lc app=leetcode id=3092 lang=kotlin */
class Solution { fun mostFrequentIDs(nums: IntArray, freq: IntArray): LongArray = HashMap<Int, Long>().let { cntMap -> java.util.TreeMap<Long, Int>().let { freqMap -> LongArray(nums.size) { i -> nums[i].let { id -> freq[i].toLong().let { f -> cntMap.getOrDefault(id, 0L).let { oldF -> (oldF + f).let { newF -> cntMap.put(id, newF).run { if (oldF > 0) (freqMap[oldF]!! - 1).let { c -> if (c == 0) freqMap.remove(oldF) else freqMap[oldF] = c } }.run { if (newF > 0) freqMap[newF] = freqMap.getOrDefault(newF, 0) + 1 }.run { freqMap.takeIf { it.isNotEmpty() }?.lastKey() ?: 0L } } } } } } } }